INSERT INTO blog_articles (title, slug, category_id, service_name, excerpt, content, meta_title, meta_description, meta_keywords, featured_image, image_url, status, created_at, updated_at)
VALUES ('Fiche Google : apparaître sur Google Maps à La Réunion en 7 étapes', 'fiche-google-reunion', (SELECT id FROM service_categories WHERE slug = 'seo'), 'Référencement local', 'Quand un client tape « plombier Saint-Pierre », trois entreprises sortent sur la carte. Voici comment en faire partie, en 7 étapes, gratuitement.', '<div class="en-bref"> <p class="en-bref-titre">En bref</p> <ul> <li>La fiche Google (Google Business Profile) est gratuite. C''est elle qui vous fait apparaître sur la carte quand un client cherche « plombier Saint-Pierre » ou « restaurant Le Tampon ».</li> <li>Google classe les fiches locales selon trois critères qu''il publie lui-même : la pertinence, la distance et la notoriété.</li> <li>Une fiche complète, avec des photos récentes, des horaires justes et des avis auxquels vous répondez, fait la plus grande partie du travail.</li> </ul> </div> <p>Quand un client cherche un artisan, un restaurant ou un cabinet à La Réunion, Google affiche souvent une carte avec quelques entreprises, avant même les sites internet. Être dans cette sélection ne coûte rien. Pourtant, beaucoup de fiches restent incomplètes, avec des horaires faux, deux photos floues et des avis sans réponse.</p> <p>Voici les 7 étapes pour créer ou remettre en état votre fiche, dans l''ordre où elles comptent.</p> <h2>Comment Google choisit les entreprises affichées sur la carte</h2> <p>Google l''explique dans son <a href="https://support.google.com/business/answer/7091" target="_blank" rel="noopener">aide officielle</a> : le classement local repose sur trois critères.</p> <table class="table-article"> <thead><tr><th>Critère</th><th>Ce que Google regarde</th><th>Ce que vous pouvez faire</th></tr></thead> <tbody> <tr><td>Pertinence</td><td>Votre fiche correspond-elle à ce que la personne cherche ?</td><td>Choisir la bonne catégorie, décrire précisément vos services</td></tr> <tr><td>Distance</td><td>À quelle distance êtes-vous du lieu de la recherche ?</td><td>Indiquer une adresse exacte et votre zone d''intervention</td></tr> <tr><td>Notoriété</td><td>Votre entreprise est-elle connue et appréciée ?</td><td>Collecter des avis, y répondre, avoir un site internet relié à la fiche</td></tr> </tbody> </table> <p>La distance ne dépend pas de vous. La pertinence et la notoriété, si : ce sont elles que les 7 étapes ci-dessous améliorent.</p> <h2>Les 7 étapes d''une fiche Google qui attire des clients</h2> <ol class="etapes"> <li><strong>Créer ou revendiquer la fiche.</strong> Rendez-vous sur <a href="https://www.google.com/business/" target="_blank" rel="noopener">Google Business Profile</a>. Votre entreprise a peut-être déjà une fiche créée par un client : revendiquez-la plutôt que d''en créer une seconde. Google vous demandera de vérifier que vous êtes bien le propriétaire.</li> <li><strong>Choisir la catégorie principale avec soin.</strong> C''est le réglage qui pèse le plus sur la pertinence. Prenez la plus précise (« Pisciniste » plutôt que « Entrepreneur »), puis ajoutez quelques catégories secondaires.</li> <li><strong>Renseigner une adresse ou une zone exacte.</strong> Si vous recevez vos clients, indiquez l''adresse. Si vous vous déplacez, comme beaucoup d''artisans, masquez l''adresse et listez les communes desservies.</li> <li><strong>Tenir les horaires à jour.</strong> Ajoutez les horaires exceptionnels pour les jours fériés, dont le 20 décembre, et pour les fermetures pendant une alerte cyclonique. Un client qui trouve porte close ne revient pas.</li> <li><strong>Décrire vos services avec les mots de vos clients.</strong> Dans la description et la liste des services, employez les termes qu''ils tapent : « entretien de piscine », « dépannage climatisation », « pose de carrelage ». Google interdit en revanche d''ajouter des mots-clés dans le nom de l''entreprise : utilisez votre vrai nom.</li> <li><strong>Ajouter de vraies photos, souvent.</strong> Façade, équipe, réalisations, intérieur. Des photos récentes et prises par vous rassurent plus qu''une image de banque d''images.</li> <li><strong>Collecter des avis et répondre à tous.</strong> Demandez un avis à chaque client satisfait, avec le lien direct de votre fiche, et répondez à chaque avis, positif ou négatif.</li> </ol> <div class="encadre-exemple"> <p class="encadre-titre">Exemple (cas fictif) : un climaticien à Saint-Paul</p> <p>Sa fiche existe, créée par un client, avec la catégorie « Électricien » et aucune photo. Il la revendique, passe en catégorie principale « Entreprise de climatisation », masque son adresse personnelle et liste les communes de l''Ouest qu''il dessert. Il ajoute dix photos de chantiers et prend l''habitude d''envoyer le lien d''avis par SMS après chaque intervention. Sa fiche correspond désormais à ce que ses clients cherchent.</p> </div> <h2>Les erreurs qui font disparaître une fiche</h2> <ul> <li><strong>Un nom avec des mots-clés</strong> (« Dupont Plomberie Pas Cher Saint-Denis 974 ») : c''est contraire aux <a href="https://support.google.com/business/answer/3038177" target="_blank" rel="noopener">règles de Google</a> et peut entraîner la suspension de la fiche.</li> <li><strong>Plusieurs fiches pour la même entreprise</strong>, ou une fiche par commune sans local réel.</li> <li><strong>De faux avis</strong>, achetés ou rédigés par des proches : Google les supprime et peut sanctionner la fiche.</li> <li><strong>Une fiche abandonnée</strong> : horaires faux, téléphone qui ne répond plus, avis sans réponse depuis des mois.</li> </ul> <h2>Relier votre fiche à votre site</h2> <p>La fiche et le site se renforcent l''un l''autre. Mettez le lien de votre site sur la fiche, et sur le site, affichez les mêmes nom, adresse et téléphone que sur la fiche, à l''identique. Une page par service et une page « Zone d''intervention » qui cite vos communes aident Google à comprendre ce que vous faites et où.</p> <div class="encadre-digita"> <p class="encadre-titre">Ce que fait DIGITA</p> <p>Notre audit SEO gratuit analyse votre site en quelques secondes et repère ce qui freine votre visibilité. Pour aller plus loin, notre offre SEO Local (390 €, payé une fois) met en ordre votre fiche Google et met en place la collecte d''avis clients.</p> <p><a href="/outils/audit-seo" class="encadre-lien">Lancer l''audit SEO gratuit</a> · <a href="/services#seo" class="encadre-lien">Voir l''offre Référencement</a></p> </div> <h2>Questions fréquentes</h2> <h3>La fiche Google est-elle payante ?</h3> <p>Non. La création et la gestion d''une fiche Google Business Profile sont gratuites. Méfiez-vous des démarchages téléphoniques qui prétendent le contraire ou promettent la première place contre paiement.</p> <h3>Peut-on avoir une fiche Google sans local commercial ?</h3> <p>Oui. Si vous vous déplacez chez vos clients, vous pouvez masquer votre adresse et indiquer une zone d''intervention, par exemple les communes du Sud. C''est le cas de nombreux artisans.</p> <h3>Combien de temps pour apparaître sur la carte ?</h3> <p>Une fiche vérifiée peut apparaître en quelques jours, mais sa position dépend de la concurrence locale et de sa notoriété. Une fiche complète, active et riche en avis progresse au fil des semaines.</p> <div class="article-sources"> <p class="encadre-titre">Sources</p> <ul> <li><a href="https://support.google.com/business/answer/7091" target="_blank" rel="noopener">Google : conseils pour améliorer votre classement local</a>.</li> <li><a href="https://support.google.com/business/answer/3038177" target="_blank" rel="noopener">Google : consignes pour représenter votre entreprise</a>.</li> <li><a href="https://www.google.com/business/" target="_blank" rel="noopener">Google Business Profile</a>.</li> </ul> </div>', 'Fiche Google : apparaître sur Maps à La Réunion', 'Créer et optimiser sa fiche Google à La Réunion : les 3 critères de classement, les 7 étapes d''une fiche complète et les erreurs qui la font disparaître.', 'fiche Google Réunion, Google Business Profile, référencement local 974, apparaître sur Google Maps', '/assets/images/blog/fiche-google-reunion.webp', '/assets/images/blog/fiche-google-reunion.webp', 'draft', NOW(), NOW())
ON CONFLICT (slug) DO NOTHING;

INSERT INTO blog_articles (title, slug, category_id, service_name, excerpt, content, meta_title, meta_description, meta_keywords, featured_image, image_url, status, created_at, updated_at)
VALUES ('Site vitrine ou page Facebook : que choisir pour une entreprise à La Réunion ?', 'site-vitrine-ou-page-facebook', (SELECT id FROM service_categories WHERE slug = 'creation-web'), 'Sites web et landing', 'Votre page Facebook suffit-elle ? Ce que chacun permet, ce qu''il coûte, et le moment où le site devient indispensable pour trouver de nouveaux clients.', '<div class="en-bref"> <p class="en-bref-titre">En bref</p> <ul> <li>Une page Facebook est gratuite et rapide à créer, mais elle ne vous appartient pas : Facebook décide de qui voit vos publications.</li> <li>Un site vitrine vous fait trouver sur Google, présente vos services de façon durable et reste à vous.</li> <li>Les deux ne s''opposent pas : la page Facebook entretient le lien avec vos clients, le site convainc ceux qui ne vous connaissent pas encore.</li> </ul> </div> <p>« J''ai déjà ma page Facebook, à quoi me servirait un site ? » À La Réunion, beaucoup d''entreprises ont démarré avec une page Facebook, et certaines fonctionnent très bien ainsi pendant des années. Mais un jour, un client demande l''adresse du site, un appel d''offres exige une présentation, ou la page perd soudain sa portée. C''est souvent là que la question se pose.</p> <p>Voici ce que chaque outil permet, ce qu''il coûte, et à quel moment le site devient indispensable.</p> <h2>Ce qu''une page Facebook fait bien</h2> <ul> <li><strong>Démarrer sans budget</strong> : la création est gratuite et prend une heure.</li> <li><strong>Garder le contact</strong> : vos abonnés voient vos nouveautés, promotions et réalisations.</li> <li><strong>Recevoir des messages</strong> : beaucoup de clients préfèrent écrire sur Messenger qu''appeler.</li> <li><strong>Profiter du bouche-à-oreille</strong> : partages, recommandations, groupes locaux de quartier ou de commune.</li> </ul> <h2>Ses limites</h2> <ul> <li><strong>Vous êtes locataire.</strong> Facebook décide de ce qu''il montre à vos abonnés, et ses règles changent sans prévenir. Un compte piraté ou suspendu, et tout disparaît.</li> <li><strong>Peu de visibilité sur Google.</strong> Quand un client cherche « menuisier Saint-André », c''est surtout votre fiche Google et votre site qui peuvent ressortir, rarement une publication Facebook.</li> <li><strong>Une information qui défile.</strong> Vos tarifs, votre zone d''intervention ou vos réalisations les plus réussies sont noyés dans le fil des publications.</li> <li><strong>Une image moins professionnelle</strong> pour certains clients, notamment les entreprises et les collectivités.</li> </ul> <h2>Page Facebook ou site vitrine : le comparatif</h2> <table class="table-article"> <thead><tr><th>Critère</th><th>Page Facebook</th><th>Site vitrine</th></tr></thead> <tbody> <tr><td>Coût de départ</td><td>Gratuit</td><td>Quelques centaines à quelques milliers d''euros</td></tr> <tr><td>Coût récurrent</td><td>Votre temps (publications)</td><td>Nom de domaine, hébergement, maintenance</td></tr> <tr><td>Trouvé sur Google</td><td>Rarement</td><td>Oui, s''il est bien référencé</td></tr> <tr><td>Propriété</td><td>Facebook</td><td>Vous (si le domaine est à votre nom)</td></tr> <tr><td>Information durable</td><td>Noyée dans le fil</td><td>Organisée en pages claires</td></tr> <tr><td>Contact direct</td><td>Messenger, commentaires</td><td>Formulaire, téléphone, prise de rendez-vous</td></tr> </tbody> </table> <h2>Quand le site devient indispensable</h2> <p>Si vous vous reconnaissez dans au moins deux de ces situations, il est temps d''avoir un site :</p> <ul class="checklist"> <li>Des clients vous cherchent sur Google et tombent sur vos concurrents.</li> <li>Vous répondez dix fois par semaine aux mêmes questions : tarifs, zone, délais.</li> <li>Vous travaillez avec des entreprises, des syndics ou des collectivités qui demandent un site.</li> <li>Vous voulez montrer vos réalisations de façon organisée, par type de chantier.</li> <li>Vous lancez de la publicité et avez besoin d''une page où envoyer les visiteurs.</li> </ul> <div class="encadre-exemple"> <p class="encadre-titre">Exemple (cas fictif) : un menuisier à Saint-André</p> <p>Sa page Facebook lui apporte des clients par le bouche-à-oreille depuis cinq ans. Mais ses prospects lui demandent souvent ses tarifs et des photos de cuisines, et un syndic lui réclame un site. Il crée un site vitrine de cinq pages, avec une galerie de réalisations par type de meuble et un formulaire de devis, et continue de publier ses chantiers sur Facebook avec un lien vers le site.</p> </div> <h2>La bonne combinaison</h2> <p>Pour la plupart des TPE, la combinaison gagnante tient en trois outils : une <strong>fiche Google</strong> pour être trouvé sur la carte, un <strong>site vitrine</strong> pour convaincre et recevoir les demandes, et une <strong>page Facebook ou Instagram</strong> pour entretenir le lien. Si votre budget ne permet qu''un seul pas aujourd''hui, une page unique (landing page) avec vos services, vos réalisations et un formulaire est un bon point de départ.</p> <div class="encadre-digita"> <p class="encadre-titre">Ce que fait DIGITA</p> <p>Pour démarrer : la Landing Essentielle, une page avec formulaire de contact, à 499 €, livrée en 5 jours ouvrés. Pour un site complet : l''offre 974, site vitrine à partir de 990 € (690 € si vous avez déjà un logo), puis 49 €/mois de maintenance sur 12 mois, hébergement compris. Pas encore de page Facebook ? Le Pack de lancement (logo et page Facebook professionnelle) coûte 499 €.</p> <p><a href="/services#sites-web" class="encadre-lien">Voir l''offre Sites web</a> · <a href="/solutions#lancement" class="encadre-lien">Le Pack de lancement</a></p> </div> <h2>Questions fréquentes</h2> <h3>Une page Facebook peut-elle remplacer un site internet ?</h3> <p>Au tout début, oui, pour une activité qui vit du bouche-à-oreille. Mais elle ne vous appartient pas, elle est peu visible sur Google et elle ne présente pas vos services de façon organisée. Dès que vous voulez être trouvé par de nouveaux clients, un site devient nécessaire.</p> <h3>Faut-il garder sa page Facebook quand on a un site ?</h3> <p>Oui, si vos clients y sont actifs. Le site présente durablement votre offre, la page entretient le lien au quotidien. Mettez un lien de l''une vers l''autre pour qu''elles se renforcent.</p> <h3>Combien coûte un site vitrine pour remplacer une page Facebook ?</h3> <p>Chez DIGITA, une page unique coûte 499 € et un site vitrine démarre à 990 € (690 € si vous avez déjà un logo), puis 49 €/mois de maintenance. Le détail des coûts est dans notre guide sur le prix d''un site internet à La Réunion.</p> <div class="article-sources"> <p class="encadre-titre">Pour aller plus loin</p> <ul> <li><a href="/blog/prix-site-internet-reunion">Prix d''un site internet à La Réunion : le vrai coût</a>.</li> <li><a href="/blog/instagram-ou-facebook-reunion">Instagram ou Facebook : où sont vos clients à La Réunion ?</a></li> <li><a href="https://support.google.com/business/answer/7091" target="_blank" rel="noopener">Google : améliorer votre classement local</a>.</li> <li>Grille tarifaire DIGITA : <a href="/tarifs">page Tarifs</a>, consultée le 7 novembre 2026.</li> </ul> </div>', 'Site vitrine ou page Facebook : que choisir en 974 ?', 'Votre page Facebook suffit-elle ? Ce que permet chaque outil, ce qu''il coûte, et les signes qui montrent qu''il est temps de créer un site vitrine.', 'site vitrine Réunion, page Facebook entreprise, créer un site internet 974, site ou Facebook', '/assets/images/blog/site-vitrine-ou-page-facebook.webp', '/assets/images/blog/site-vitrine-ou-page-facebook.webp', 'draft', NOW(), NOW())
ON CONFLICT (slug) DO NOTHING;

INSERT INTO blog_articles (title, slug, category_id, service_name, excerpt, content, meta_title, meta_description, meta_keywords, featured_image, image_url, status, created_at, updated_at)
VALUES ('Gîte à La Réunion : 6 réglages pour remplir la haute saison', 'gite-reunion-haute-saison', (SELECT id FROM service_categories WHERE slug = 'seo'), 'Tourisme', 'Décembre et janvier se jouent maintenant. Fiche Google, photos, avis, réservation directe : la liste à cocher avant les vacances australes.', '<div class="en-bref"> <p class="en-bref-titre">En bref</p> <ul> <li>Les voyageurs choisissent un hébergement sur les photos, les avis et la rapidité de réponse : ce sont les trois leviers à travailler avant les vacances.</li> <li>La réservation directe (site ou page dédiée) vous évite une partie des commissions des plateformes, à condition d''inspirer autant confiance qu''elles.</li> <li>À La Réunion, deux spécificités comptent : le décalage horaire avec la métropole et les conditions d''annulation en cas d''alerte cyclonique.</li> </ul> </div> <p>Les grandes vacances australes, de mi-décembre à janvier, sont un temps fort pour les gîtes, chambres d''hôtes et locations de l''île. Mais les réservations se jouent bien avant : les familles comparent, posent des questions et réservent souvent plusieurs semaines à l''avance. Un hébergement mal présenté en ligne à ce moment-là laisse passer sa saison.</p> <p>Voici six réglages à faire maintenant, du plus simple au plus rentable.</p> <h2>1. Une fiche Google complète et à jour</h2> <p>Beaucoup de voyageurs cherchent directement sur Google Maps : « gîte Cilaos », « chambre d''hôtes Saint-Leu ». Vérifiez que votre <a href="/blog/fiche-google-reunion">fiche Google</a> a la bonne catégorie, votre lien de réservation, un numéro joignable et des photos récentes. Indiquez vos horaires d''accueil et d''arrivée.</p> <h2>2. Des photos qui répondent aux questions</h2> <p>Une bonne photo montre ce que le voyageur veut savoir, pas seulement ce qui est joli.</p> <ul> <li>Chaque pièce, prise à la lumière du jour, depuis l''angle de la porte.</li> <li>La vue et l''extérieur : terrasse, jardin, piscine, varangue.</li> <li>Les équipements qui font la différence : climatisation, cuisine équipée, lit bébé, parking.</li> <li>L''accès : la route, le stationnement, l''entrée. À l''écart des grands axes, c''est une vraie question.</li> </ul> <h2>3. Des avis récents et des réponses à chacun</h2> <p>Un avis datant de deux ans pèse peu. Demandez un avis à chaque client satisfait, juste après son départ, avec le lien direct. Et répondez à tous : un remerciement personnalisé pour un avis positif, une réponse calme et factuelle pour une critique. Les futurs clients lisent autant vos réponses que les avis eux-mêmes. Notre guide sur les <a href="/blog/avis-google-entreprise">avis Google</a> détaille la méthode.</p> <h2>4. Une page de réservation directe</h2> <p>Les plateformes de réservation apportent de la visibilité, mais prélèvent une commission sur chaque séjour. Une page à vous, avec vos disponibilités, vos tarifs, vos conditions et un formulaire ou un paiement, permet aux clients fidèles et à ceux qui vous trouvent sur Google de réserver en direct.</p> <p>Pour inspirer confiance, cette page doit afficher les mêmes informations que les plateformes : photos, équipements, conditions d''annulation, avis, et vos coordonnées complètes.</p> <h2>5. Répondre vite, malgré le décalage horaire</h2> <p>Une partie de vos clients écrit depuis la métropole, avec 2 à 3 heures de décalage selon la saison. Une question envoyée à 21 h à Paris arrive chez vous vers minuit. Le voyageur qui attend la réponse jusqu''au lendemain midi a souvent réservé ailleurs.</p> <ul> <li><strong>Le minimum</strong> : un message d''accueil automatique sur Messenger, Instagram et <a href="https://business.whatsapp.com/products/business-app" target="_blank" rel="noopener">WhatsApp Business</a>, qui donne le lien des disponibilités et le délai de réponse.</li> <li><strong>Plus loin</strong> : un <a href="/blog/agent-ia-repondre-clients-24h">agent IA</a> qui répond aux questions courantes (accès, équipements, dates libres) et vous transmet les demandes déjà qualifiées.</li> </ul> <h2>6. Des conditions claires pour la saison des cyclones</h2> <p>De janvier à mars, la saison cyclonique inquiète les voyageurs qui ne connaissent pas l''île. Indiquez clairement ce qui se passe en cas d''alerte : report des dates, remboursement, ou conditions de la plateforme. Une règle écrite noir sur blanc rassure et évite les litiges.</p> <div class="encadre-exemple"> <p class="encadre-titre">Exemple (cas fictif) : deux gîtes à Cilaos</p> <p>La propriétaire a 40 photos sur sa page, mais aucune ne montre la route d''accès, et elle reçoit chaque semaine la même question sur le stationnement. Elle ajoute trois photos de l''accès et du parking, un paragraphe « Comment venir » et un message automatique avec le lien de ses disponibilités. Les questions répétitives diminuent et les demandes qu''elle reçoit sont plus précises.</p> </div> <h2>Le rappel réglementaire</h2> <p>Louer un meublé de tourisme impose des démarches, dont une déclaration ou un enregistrement auprès de la mairie, selon les cas. <a href="https://www.service-public.fr/particuliers/vosdroits/F2043" target="_blank" rel="noopener">Service Public</a> détaille les obligations. Vérifiez aussi auprès de votre commune les règles qui s''appliquent localement.</p> <div class="encadre-digita"> <p class="encadre-titre">Ce que fait DIGITA</p> <p>Nous créons votre page de réservation directe (Landing Essentielle à 499 €, ou site vitrine à partir de 990 €), mettons en ordre votre fiche Google (SEO Local, 390 €) et, si vous recevez beaucoup de messages, branchons un agent qui répond jour et nuit sur Messenger et Instagram.</p> <p><a href="/services#sites-web" class="encadre-lien">Voir l''offre Sites web</a> · <a href="/diagnostic" class="encadre-lien">Réserver un diagnostic gratuit</a></p> </div> <h2>Questions fréquentes</h2> <h3>Faut-il quitter les plateformes de réservation pour la réservation directe ?</h3> <p>Non. Les plateformes apportent de la visibilité auprès de voyageurs qui ne vous connaissent pas. La réservation directe complète ce canal pour les clients fidèles et ceux qui vous trouvent sur Google. Vérifiez seulement que vos calendriers sont synchronisés pour éviter les doubles réservations.</p> <h3>Combien de photos faut-il pour une annonce de gîte ?</h3> <p>Il n''y a pas de nombre magique, mais chaque pièce, l''extérieur, la vue, les équipements importants et l''accès doivent être montrés. Mieux vaut vingt photos utiles et lumineuses que cinquante photos répétitives.</p> <h3>Comment répondre aux voyageurs la nuit sans y passer ses soirées ?</h3> <p>Activez un message d''accueil automatique sur vos messageries avec le lien de vos disponibilités et votre délai de réponse. Si les questions sont nombreuses, un agent IA peut répondre aux plus courantes et vous transmettre les demandes de réservation.</p> <div class="article-sources"> <p class="encadre-titre">Sources</p> <ul> <li><a href="https://www.service-public.fr/particuliers/vosdroits/F2043" target="_blank" rel="noopener">Service Public : faire de sa résidence une location de vacances (meublé de tourisme)</a>.</li> <li><a href="https://support.google.com/business/answer/7091" target="_blank" rel="noopener">Google : améliorer votre classement local</a>.</li> <li><a href="https://www.reunion.fr/" target="_blank" rel="noopener">Île de La Réunion Tourisme</a> : informations pratiques pour les visiteurs.</li> <li><a href="https://business.whatsapp.com/products/business-app" target="_blank" rel="noopener">WhatsApp Business</a> : messages automatiques.</li> </ul> </div>', 'Gîte à La Réunion : 6 réglages pour la haute saison', 'Fiche Google, photos, avis, réservation directe, réponses rapides et conditions cycloniques : la liste pour remplir votre gîte pendant les vacances.', 'gîte Réunion, location saisonnière 974, réservation directe gîte, chambre d''hôtes La Réunion', '/assets/images/blog/gite-reunion-haute-saison.webp', '/assets/images/blog/gite-reunion-haute-saison.webp', 'draft', NOW(), NOW())
ON CONFLICT (slug) DO NOTHING;

INSERT INTO blog_articles (title, slug, category_id, service_name, excerpt, content, meta_title, meta_description, meta_keywords, featured_image, image_url, status, created_at, updated_at)
VALUES ('Répondre aux clients pendant les fêtes sans y passer ses soirées', 'repondre-clients-pendant-les-fetes', (SELECT id FROM service_categories WHERE slug = 'intelligence-artificielle'), 'Agents IA', 'Messages d''absence, réponses rapides, agent IA : trois niveaux pour rester joignable quand l''entreprise est fermée, avec des modèles prêts à copier.', '<div class="en-bref"> <p class="en-bref-titre">En bref</p> <ul> <li>Pendant les fêtes, un client sans réponse ne revient pas forcément en janvier : il contacte le suivant sur la liste.</li> <li>Trois niveaux permettent de rester joignable sans travailler le soir : les messages automatiques gratuits, les réponses préparées, puis l''agent IA.</li> <li>Le premier niveau se met en place en une heure, avec les outils que vous avez déjà.</li> </ul> </div> <p>Décembre est un mois paradoxal pour beaucoup d''entreprises réunionnaises : les clients écrivent davantage (cadeaux, réservations, travaux à finir avant l''année), alors que vous voulez enfin souffler en famille. Entre le 20 décembre, Noël et le jour de l''An, les messages s''accumulent, et chaque demande laissée sans réponse est une occasion perdue.</p> <p>La solution n''est pas de répondre à minuit depuis le canapé. C''est de préparer, avant les fêtes, des réponses qui travaillent pour vous.</p> <h2>Niveau 1 : les messages automatiques gratuits</h2> <p>Ils ne répondent pas à la question, mais ils évitent le pire : le silence. Le client sait que sa demande est bien reçue et quand il aura une réponse.</p> <table class="table-article"> <thead><tr><th>Canal</th><th>Réglage</th><th>Où le trouver</th></tr></thead> <tbody> <tr><td>WhatsApp Business</td><td>Message d''absence et message d''accueil</td><td>Outils professionnels de l''application</td></tr> <tr><td>Messenger et Instagram</td><td>Réponses instantanées et message d''absence</td><td>Meta Business Suite, boîte de réception</td></tr> <tr><td>E-mail</td><td>Réponse automatique avec dates de fermeture</td><td>Paramètres de votre messagerie</td></tr> <tr><td>Téléphone</td><td>Annonce de répondeur mise à jour</td><td>Votre opérateur ou votre téléphone</td></tr> <tr><td>Fiche Google</td><td>Horaires exceptionnels des jours fériés</td><td>Google Business Profile</td></tr> </tbody> </table> <div class="encadre-exemple"> <p class="encadre-titre">Modèle de message d''absence à adapter</p> <p>« Bonjour et merci pour votre message ! Nous sommes en congés du 24 décembre au 2 janvier. Nous vous répondrons dès le 3 janvier. Pour un devis, vous pouvez déjà nous envoyer vos besoins et quelques photos : nous traiterons votre demande en priorité à notre retour. Bonnes fêtes ! »</p> </div> <h2>Niveau 2 : les réponses préparées</h2> <p>La plupart des messages de fin d''année posent les mêmes questions : êtes-vous ouverts, jusqu''à quand peut-on commander, livrez-vous avant Noël, quels sont vos tarifs. Préparez-les une fois pour toutes.</p> <ul> <li><strong>Les réponses rapides</strong> de WhatsApp Business et de Meta Business Suite : un raccourci affiche une réponse complète en deux secondes.</li> <li><strong>Une page « Infos fêtes »</strong> sur votre site ou en publication épinglée : horaires, dates limites de commande, conditions de livraison, contact d''urgence.</li> <li><strong>Un formulaire de demande</strong> qui recueille tout ce qu''il vous faut (besoin, commune, délai, photos). En janvier, vous traitez des demandes complètes au lieu de relancer chaque client.</li> </ul> <h2>Niveau 3 : l''agent IA qui répond vraiment</h2> <p>Si vous recevez beaucoup de messages, un <a href="/blog/agent-ia-repondre-clients-24h">agent IA</a> va plus loin : il répond aux questions à partir de vos informations, qualifie la demande et propose un rendez-vous à votre retour. Il doit dire au client qu''il s''agit d''un assistant automatique et vous transmettre ce qu''il ne sait pas traiter.</p> <p>Ce niveau demande quelques semaines de préparation et de tests : c''est un projet à lancer en novembre pour les fêtes, ou dès maintenant pour l''année qui vient.</p> <h2>Organiser l''équipe pendant les congés</h2> <ul class="checklist"> <li>Décider qui consulte les messages, et à quelle fréquence (par exemple une fois par jour, le matin).</li> <li>Définir ce qui est urgent (une panne, une livraison bloquée) et un seul canal pour ces urgences.</li> <li>Mettre à jour les horaires sur la fiche Google, le site, la page Facebook et le répondeur, le même jour.</li> <li>Prévoir une réponse à chaque message en attente dès le retour, dans l''ordre d''arrivée.</li> </ul> <div class="encadre-digita"> <p class="encadre-titre">Ce que fait DIGITA</p> <p>Nous mettons en place vos messages automatiques et vos réponses rapides, ou un agent IA qui répond jour et nuit sur Messenger et Instagram : mise en service de 490 € à 890 €, puis 149 € à 249 €/mois, jusqu''à 300 conversations par mois. Le formulaire de demande peut alimenter directement votre tableau de suivi (automatisation à partir de 490 €).</p> <p><a href="/agent24-7" class="encadre-lien">Découvrir INES, l''agent IA</a> · <a href="/services#ia-automation" class="encadre-lien">Voir l''offre Automatisation</a></p> </div> <h2>Questions fréquentes</h2> <h3>Comment activer un message d''absence sur WhatsApp Business ?</h3> <p>Dans l''application WhatsApp Business, ouvrez les outils professionnels, puis le message d''absence. Rédigez votre texte, choisissez les dates ou les heures de diffusion et les destinataires, puis activez-le.</p> <h3>Un message automatique peut-il faire perdre des clients ?</h3> <p>Un message clair, chaleureux et daté rassure plus qu''un silence. Indiquez quand vous répondrez et ce que le client peut déjà envoyer, par exemple ses besoins et des photos, pour que sa demande soit traitée en priorité à votre retour.</p> <h3>Faut-il un agent IA pour les fêtes ?</h3> <p>Pas forcément. Pour la plupart des TPE, les messages automatiques et les réponses préparées suffisent. Un agent IA devient utile quand les messages sont nombreux et que chaque réponse rapide peut se transformer en vente ou en réservation.</p> <div class="article-sources"> <p class="encadre-titre">Sources</p> <ul> <li><a href="https://business.whatsapp.com/products/business-app" target="_blank" rel="noopener">WhatsApp Business</a> : message d''absence, message d''accueil, réponses rapides.</li> <li><a href="https://www.facebook.com/business/tools/meta-business-suite" target="_blank" rel="noopener">Meta Business Suite</a> : boîte de réception et réponses automatiques.</li> <li><a href="https://www.google.com/business/" target="_blank" rel="noopener">Google Business Profile</a> : horaires exceptionnels.</li> <li>Offres DIGITA : <a href="/solutions">page Solutions</a>, consultée le 7 novembre 2026.</li> </ul> </div>', 'Répondre aux clients pendant les fêtes', 'Messages d''absence, réponses préparées, agent IA : trois niveaux pour rester joignable pendant les fêtes de fin d''année sans travailler le soir.', 'message d''absence WhatsApp Business, réponse automatique clients, fermeture fêtes entreprise, agent IA', '/assets/images/blog/repondre-clients-pendant-les-fetes.webp', '/assets/images/blog/repondre-clients-pendant-les-fetes.webp', 'draft', NOW(), NOW())
ON CONFLICT (slug) DO NOTHING;

INSERT INTO blog_articles (title, slug, category_id, service_name, excerpt, content, meta_title, meta_description, meta_keywords, featured_image, image_url, status, created_at, updated_at)
VALUES ('Avis Google : en obtenir plus et répondre aux mauvais', 'avis-google-entreprise', (SELECT id FROM service_categories WHERE slug = 'seo'), 'Référencement local', 'Un avis sans réponse se lit comme un aveu. La routine pour collecter des avis chaque semaine, ce que Google interdit, et des modèles de réponse.', '<div class="en-bref"> <p class="en-bref-titre">En bref</p> <ul> <li>Google indique que le nombre d''avis et la note comptent dans le classement local : les avis jouent sur votre visibilité autant que sur la confiance.</li> <li>Pour en obtenir plus, demandez au bon moment, avec un lien direct, à chaque client satisfait. Offrir une contrepartie ou ne solliciter que les clients contents est interdit par Google.</li> <li>Répondez à tous les avis. Une critique bien traitée rassure souvent plus qu''une série de cinq étoiles sans réponse.</li> </ul> </div> <p>Avant d''appeler un artisan ou de réserver une table, la plupart des gens regardent la note et les derniers avis. À La Réunion, où tout le monde finit par connaître quelqu''un qui connaît l''entreprise, la réputation en ligne prolonge le bouche-à-oreille. Une fiche avec trois avis anciens et une critique sans réponse fait fuir des clients que vous ne verrez jamais.</p> <p>Voici comment obtenir des avis régulièrement, en respectant les règles, et comment répondre à chacun, même aux mauvais.</p> <h2>Pourquoi les avis comptent autant</h2> <p>Dans son <a href="https://support.google.com/business/answer/7091" target="_blank" rel="noopener">aide sur le classement local</a>, Google explique que la notoriété d''une entreprise fait partie des critères, et que le nombre d''avis et leur note y contribuent. Les avis jouent donc deux rôles : ils vous font remonter sur la carte, et ils convainquent le client qui hésite entre vous et un concurrent.</p> <h2>Obtenir plus d''avis : la routine en 4 points</h2> <ol class="etapes"> <li><strong>Récupérer votre lien d''avis.</strong> Depuis votre fiche Google, copiez le lien qui ouvre directement la fenêtre de dépôt d''avis. Créez aussi un QR code à partir de ce lien pour votre comptoir, vos factures ou votre véhicule.</li> <li><strong>Demander au bon moment.</strong> Juste après une intervention réussie, une livraison ou un séjour, quand le client est satisfait et a encore l''expérience en tête.</li> <li><strong>Demander personnellement, puis par écrit.</strong> « Si vous êtes content du travail, un avis Google nous aiderait beaucoup », puis un SMS ou un message avec le lien dans la journée. Sans insister et sans suggérer ce qu''il faut écrire : Google l''interdit aussi.</li> <li><strong>En faire une habitude.</strong> Une demande à chaque client, chaque semaine, vaut mieux qu''une grande campagne une fois par an. Des avis réguliers et récents inspirent plus confiance.</li> </ol> <div class="encadre-exemple"> <p class="encadre-titre">Modèle de SMS à adapter</p> <p>« Bonjour Mme Payet, merci encore pour votre confiance pour la pose de votre carrelage. Si vous êtes satisfaite, un petit avis Google nous aiderait beaucoup : [lien]. Bonne journée ! »</p> </div> <h2>Ce qui est interdit</h2> <p>Les <a href="https://support.google.com/contributionpolicy/answer/7400114" target="_blank" rel="noopener">règles de Google sur les contenus</a> interdisent les faux avis et les avis obtenus en échange d''une contrepartie. Concrètement :</p> <ul> <li><strong>Pas de remise ou de cadeau contre un avis</strong>, même « pour un avis honnête ».</li> <li><strong>Pas de tri des clients</strong> : ne demander un avis qu''aux clients contents, après les avoir filtrés, est aussi contraire aux règles de Google.</li> <li><strong>Pas d''avis rédigés par vous, vos proches ou vos salariés</strong>, ni d''avis achetés.</li> <li><strong>Pas de faux avis négatifs</strong> sur un concurrent.</li> </ul> <p>Google supprime ces avis et peut restreindre la fiche. En France, publier de faux avis peut aussi constituer une pratique commerciale trompeuse.</p> <h2>Répondre aux avis, positifs comme négatifs</h2> <p>Google encourage à <a href="https://support.google.com/business/answer/3474050" target="_blank" rel="noopener">répondre aux avis</a>. Vos réponses sont publiques : elles s''adressent autant au client qu''à tous ceux qui les liront ensuite.</p> <table class="table-article"> <thead><tr><th>Type d''avis</th><th>Ce qu''il faut faire</th><th>À éviter</th></tr></thead> <tbody> <tr><td>Positif</td><td>Remercier avec un détail précis (le chantier, le plat, la chambre)</td><td>La même phrase copiée sous tous les avis</td></tr> <tr><td>Mitigé</td><td>Remercier, reconnaître le point faible, dire ce qui change</td><td>Se justifier point par point</td></tr> <tr><td>Négatif fondé</td><td>S''excuser, proposer d''en parler par téléphone ou message</td><td>Répondre à chaud, accuser le client</td></tr> <tr><td>Faux ou injurieux</td><td>Le signaler à Google depuis la fiche, répondre sobrement</td><td>Polémiquer publiquement</td></tr> </tbody> </table> <div class="encadre-exemple"> <p class="encadre-titre">Modèle de réponse à un avis négatif</p> <p>« Bonjour M. Hoarau, merci d''avoir pris le temps de nous écrire, et désolés pour ce retard sur votre chantier. Ce n''est pas le service que nous voulons vous offrir. Pouvez-vous nous appeler au [numéro] ? Nous voulons trouver une solution avec vous. »</p> </div> <div class="encadre-digita"> <p class="encadre-titre">Ce que fait DIGITA</p> <p>Notre offre SEO Local (390 €, payé une fois) met en ordre votre fiche Google et installe une collecte d''avis simple : lien direct, QR code, message type envoyé après chaque prestation. Nous pouvons aussi automatiser l''envoi de la demande d''avis quand un chantier ou une commande est terminé.</p> <p><a href="/services#seo" class="encadre-lien">Voir l''offre Référencement</a> · <a href="/outils/audit-seo" class="encadre-lien">Lancer l''audit SEO gratuit</a></p> </div> <h2>Questions fréquentes</h2> <h3>Peut-on supprimer un avis Google négatif ?</h3> <p>Vous ne pouvez pas supprimer vous-même un avis. Si l''avis enfreint les règles de Google (faux avis, propos injurieux, hors sujet, conflit d''intérêts), signalez-le depuis votre fiche. Sinon, la meilleure option est une réponse calme et constructive.</p> <h3>A-t-on le droit d''offrir une réduction contre un avis ?</h3> <p>Non. Les règles de Google interdisent d''offrir une contrepartie en échange d''un avis, même si vous demandez un avis honnête. Ces avis peuvent être supprimés et la fiche sanctionnée.</p> <h3>Faut-il répondre à tous les avis Google ?</h3> <p>Oui, autant que possible, et assez vite. Une réponse personnalisée montre que l''entreprise est active et à l''écoute. Pour les avis négatifs, elle montre aux futurs clients comment vous gérez un problème.</p> <div class="article-sources"> <p class="encadre-titre">Sources</p> <ul> <li><a href="https://support.google.com/business/answer/7091" target="_blank" rel="noopener">Google : conseils pour améliorer votre classement local</a>.</li> <li><a href="https://support.google.com/business/answer/3474122" target="_blank" rel="noopener">Google : conseils pour obtenir plus d''avis</a>.</li> <li><a href="https://support.google.com/business/answer/3474050" target="_blank" rel="noopener">Google : gérer les avis clients</a>.</li> <li><a href="https://support.google.com/contributionpolicy/answer/7400114" target="_blank" rel="noopener">Google Maps : contenus interdits et restreints</a>.</li> </ul> </div>', 'Avis Google : en obtenir plus et répondre aux mauvais', 'Comment obtenir plus d''avis Google en respectant les règles, et comment répondre aux avis négatifs. Méthode, interdits et modèles de réponse.', 'avis Google entreprise, obtenir des avis clients, répondre avis négatif, e-réputation Réunion', '/assets/images/blog/avis-google-entreprise.webp', '/assets/images/blog/avis-google-entreprise.webp', 'draft', NOW(), NOW())
ON CONFLICT (slug) DO NOTHING;
